inventory = {'Apples': 50, 'Bananas': 30}

def add_item(item, qty):
    inventory[item] = inventory.get(item, 0) + qty

def sell_item(item, qty):
    if item in inventory and inventory[item] >= qty:
        inventory[item] -= qty
    else:
        print('Insufficient Stock or Item not found')

add_item('Oranges', 20)
sell_item('Apples', 10)
