def longest_increasing_seq(arr):
    if not arr: return []
    max_seq, current_seq = [], [arr[0]]
    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            current_seq.append(arr[i])
        else:
            if len(current_seq) > len(max_seq):
                max_seq = current_seq
            current_seq = [arr[i]]
    if len(current_seq) > len(max_seq):
        max_seq = current_seq
    return max_seq

print(longest_increasing_seq([4, 1, 2, 3, 1, 5]))
```

