names = ['Alice', 'Bob', 'Amanda', 'Charlie', 'Brian']
name_dict = {}
for name in names:
    first_char = name[0].upper()
    if first_char not in name_dict:
        name_dict[first_char] = []
    name_dict[first_char].append(name)

for k in sorted(name_dict.keys()):
    print(k, ':', name_dict[k])
```
